const body = $json.body || {};
// Esperado desde front o cliente: { studentId?, question, courseId?, career?, profile? }
const question = (body.question || '').toString().trim();
const courseId = (body.courseId || '').toString().trim();
const studentId = (body.studentId || '').toString().trim();
// Perfil enviado por el cliente (opcional, mientras no haya Supabase)
const profileFromClient = body.profile || null; // {name?, career?, semester?, interests?, completedCourses?, enrolledCourses?}
return [{ json: { question, courseId, studentId, profileFromClient } }];

let intentRaw = $json?.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
try { intentRaw = JSON.parse(intentRaw); } catch(e) { intentRaw = { intencion: 'otro', tema: '' }; }
const intencion = intentRaw.intencion || 'otro';
const tema = (intentRaw.tema || '').toString();
return [{ json: { ...$items('Set Inputs',0)[0].json, intencion, tema } }];

let nq = $json?.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
try { nq = JSON.parse(nq); } catch(e) { nq = { pregunta_clara: $items('Set Inputs',0)[0].json.question || '' }; }
return [{ json: { ...$items('Parse Intent',0)[0].json, preguntaClara: nq.pregunta_clara || $items('Set Inputs',0)[0].json.question } }];

const pFromApi = $json?.data || null;
const pFromClient = $items('Carry Normalized Question',0)[0].json.profileFromClient || null;
// Prioridad: Supabase > Cliente > vacío
const profile = pFromApi || pFromClient || null;
return [{ json: { ...$items('Carry Normalized Question',0)[0].json, profile } }];

const emb = $json?.embedding?.values || [];
const embeddingStr = Array.isArray(emb) && emb.length ? `[${emb.join(',')}]` : '[]';
const safeCourse = $items('Merge Profile',0)[0].json.courseId || '';
const studentId = $items('Merge Profile',0)[0].json.studentId || '';
const preguntaClara = $items('Merge Profile',0)[0].json.preguntaClara || '';
const intencion = $items('Parse Intent',0)[0].json.intencion || 'otro';
const tema = $items('Parse Intent',0)[0].json.tema || '';
const profile = $items('Merge Profile',0)[0].json.profile || null;
return [{ json: { courseId: safeCourse, studentId, preguntaClara, intencion, tema, embeddingStr, profile } }];

const rows = $items('Search Context (Postgres)')?.map(i => (i.json.content || '').trim()) || [];
const context = [...new Set(rows)].filter(Boolean).map(s => s.slice(0, 1800)).join('\n---\n');
const profile = $items('Map Embedding + Carry',0)[0].json.profile || null;
let profileSummary = '';
if (profile) {
  const career = profile.career || profile.carrera || '';
  const semester = profile.semester || profile.semestre || '';
  const interests = Array.isArray(profile.interests) ? profile.interests.slice(0,5).join(', ') : (profile.interests || '');
  const enrolled = Array.isArray(profile.enrolledCourses) ? profile.enrolledCourses.slice(0,6).join(', ') : '';
  profileSummary = `Perfil Estudiante:\n- Carrera: ${career}\n- Semestre: ${semester}\n- Intereses: ${interests}\n- Materias cursando: ${enrolled}`.trim();
} else {
  profileSummary = 'Perfil del estudiante aún no disponible. Estas personalizaciones aparecerán cuando se conecte Supabase (plan de materias, avance, intereses).';
}
return [{ json: { context, profileSummary, ...$items('Map Embedding + Carry',0)[0].json } }];

