const answer = $json?.candidates?.[0]?.content?.parts?.[0]?.text?.trim() || '';
const noContext = !($items('Format Context',0)[0].json.context || '').trim();
const final = answer || (noContext ? 'Aún no tengo acceso a tu material o perfil; estas funciones estarán disponibles cuando se conecte Supabase.' : 'No encuentro esa información en el material del curso.');
return [{ json: { answer: final } }];
